fun majorityOfAnElement(arr:IntArray):Int{

    val frequencyHeap = hashMapOf<Int,Int>()

    for (i in 0..<arr.size){
        frequencyHeap[arr[i]] = frequencyHeap.getOrDefault(arr[i],0)+1
    }

    var majorityElement = 0
    var frequencyMaxCount = 0

    for (i in frequencyHeap){
        if (i.value >= arr.size/2 && i.value >= frequencyMaxCount){
            frequencyMaxCount = Math.max(frequencyMaxCount,i.value)
            majorityElement = Math.max(majorityElement,i.key)

        }
    }

    println("Frequencety Check : ${frequencyHeap.toString()}")

    return majorityElement

}

